vec2 mainSound(int s, float t) {
  vec2 r = vec2(0.0); // FIX 1: Inizializzato a zero

  // FIX 2: i e j inizializzati a zero
  for(float i = 0.0, j = 0.0; ++i < 4.0;)
  for(j = 0.0; ++j < 5.0;) {

    float a = t * j / 32.0 + i / 3.0;
    float b = fract(a);
    float c;

    // FIX 3: m inizializzato a zero
    vec2 m = vec2(0.0); 
    vec2 n = vec2(t, t + 3.0) + t / j;

    for(c = 3.0; c < 4.1; n += c *= 1.02)
      m += sin(n * c) / c;

    if(a < 9.0)
      r += sin(m + 4.0 * sin(t / j / 47.0) * sin(exp2(mod(a - b, 3.0) / 6.0 + 8.5) * t * j * i + i + j))
      * exp2(-b * 12.0 - 1.0 / b + 6.0 - (i + j) / 3.0);
  }
  // Fade-in di ~5ms: a t=0 il segnale vale -0.359 (non zero); la rampa porta l'output
  // da 0 al valore pieno nei primi 5ms per attenuare il pop di avvio (impercettibile).
  return r * smoothstep(0.0, 0.005, t);
}
//SOUND_END

// Distanza dal centro (asse Y) per gli anelli
float dist = pModel.y;

// 'fract' crea strisce nette (anelli); -u_time li espande verso l'esterno
float anelli = fract(dist * 10.0 - ubuf.u_time * 2.0);

// Bordi leggermente sfumati
anelli = smoothstep(0.0, 0.2, anelli) * smoothstep(1.0, 0.8, anelli);

// Fondo = u_col2, anelli = u_col1 (colori del dock)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, anelli);
